				gBgBot = Instance.new(LUAOBFUSACTOR_DECRYPT_STR_0("\212\176\220\235\65\249\184\194\227\100\227\176", "\35\150\217\176\135"));
				gBgBot.Name = LUAOBFUSACTOR_DECRYPT_STR_0("\212\125\89\51\80\86\120\198\117\56\60\72\97\121\237", "\22\153\48\107\108\23\35");
				gBgBot.Adornee = gunPart;
				gBgBot.Size = UDim2.new(0, 100, 0, 16);
				gBgBot.StudsOffset = Vector3.new(0, -1.4, 0);
				gBgBot.AlwaysOnTop = true;
				gBgBot.Parent = gunPart;
				self.ESP.GunBillboardBot = gBgBot;
				local lDist = Instance.new("TextLabel");
				lDist.Name = LUAOBFUSACTOR_DECRYPT_STR_0("\41\144\181\62\118\102\85\197\15\135\190\22", "\137\110\229\219\122\31\21\33");
				lDist.Size = UDim2.new(1, 0, 1, 0);
				lDist.BackgroundTransparency = 1;
				lDist.Font = Enum.Font.GothamBold;
				lDist.TextSize = 12;
				lDist.TextColor3 = Color3.fromRGB(255, 255, 255);
				lDist.Text = "0m";
