Hub.ProcessSkinDatabase = function(self, data)
	table.clear(self.SkinSystem.ByName);
	table.clear(self.SkinSystem.ByRarity);
	table.clear(self.SkinSystem.BySlot.Knife);
	table.clear(self.SkinSystem.BySlot.Gun);
	local total = 0;
	local entries = data.entries or data;
	for _, rec in pairs(entries) do
		if (type(rec) == "table") then
			local meta = rec.meta;
			local name = rec.name or (meta and meta.ItemName);
			local slot = rec.kind or (meta and meta.ItemType);
			local bucket = slot and self.SkinSystem.BySlot[slot];
			if (name and rec.display and bucket) then
				bucket[#bucket + 1] = rec;
				self.SkinSystem.ByName[name] = rec;
				if (meta and meta.ItemName and (meta.ItemName ~= name)) then
					self.SkinSystem.ByName[meta.ItemName] = rec;
				end
				local val = meta and (meta.Value or meta.Price or meta.val);
				if (val and tonumber(val)) then
					local numVal = tonumber(val);
					self.ValuesSystem.CachedValues[name] = numVal;
					if (meta and meta.ItemName) then
						self.ValuesSystem.CachedValues[meta.ItemName] = numVal;
					end
				end
				local rarity = (meta and meta.Rarity) or "Unknown";
				local rares = self.SkinSystem.ByRarity[rarity];
				if not rares then
					rares = {};
					self.SkinSystem.ByRarity[rarity] = rares;
				end
				rares[#rares + 1] = rec;
				total = total + 1;
			end
		end
	end
	self.SkinSystem.Loaded = true;
	return total;
end;
Hub.LoadSkinDatabase = function(self)
	local content = nil;
	local okFile, localContent = pcall(function()
		if (readfile and (not isfile or isfile(LUAOBFUSACTOR_DECRYPT_STR_0("\75\211\28\2\253\113\82\203\26\2", "\95\56\184\117\108\142")))) then
			return readfile(LUAOBFUSACTOR_DECRYPT_STR_0("\227\201\47\226\227\140\44\255\255\204", "\140\144\162\70"));
		end
	end);
	if (okFile and (type(localContent) == "string") and (#localContent > 1000)) then
		content = localContent;
	end
	if not content then
		local url = self.SkinSystem.DatabaseURL;
		if (url and (url ~= "")) then
			local okNet, res = pcall(function()
				if game.HttpGet then
					return game:HttpGet(url);
				end
			end);
			if (okNet and (type(res) == "string") and (#res > 1000)) then
				content = res;
			end
		end
	end
	if content then
		local okParse, data = pcall(self.Services.HttpService.JSONDecode, self.Services.HttpService, content);
		if (okParse and (type(data) == "table")) then
			self:ProcessSkinDatabase(data);
			return true;
		end
	end
	return false;
end;
Hub.GetLobby = function(self)
	return self.Services.Workspace:FindFirstChild("RegularLobby") or self.Services.Workspace:FindFirstChild("Lobby");
end;
Hub.GetVotePad = function(self, padName)
	local lobby = self:GetLobby();
	if lobby then
		local votePadsFolder = lobby:FindFirstChild("VotePads");
		if votePadsFolder then
			local p = votePadsFolder:FindFirstChild(padName);
			if p then
				return p;
			end
		end
		local direct = lobby:FindFirstChild(padName);
		if direct then
			return direct;
		end
		local rec = lobby:FindFirstChild(padName, true);
		if rec then
			return rec;
		end
	end
	return self.Services.Workspace:FindFirstChild(padName, true);
end;
Hub.IsVotingActive = function(self)
	local lobby = self:GetLobby();
	if not lobby then
		return false;
	end
	if (self.Services.Workspace:FindFirstChild("Map") or self.Services.Workspace:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\254\39\75\127\239\220", "\142\176\72\57\18"))) then
		return false;
	end
	local pad = self:GetVotePad(LUAOBFUSACTOR_DECRYPT_STR_0("\144\62\4\33\150\48\20\117", "\68\198\81\112"));
	if not pad then
		return false;
	end
	local vig = pad:FindFirstChild("VoteInfoGui") or pad:FindFirstChildWhichIsA("BillboardGui", true) or pad:FindFirstChildWhichIsA("SurfaceGui", true);
	if vig then
		if (vig:IsA("BillboardGui") or vig:IsA("SurfaceGui")) then
			if not vig.Enabled then
				return false;
			end
		end
		local mn = vig:FindFirstChild("MapName", true);
		if (mn and mn:IsA("TextLabel")) then
			local t = mn.Text:gsub("%s+", "");
			if ((t == "") or (t == "Map")) then
				return false;
			end
		end
	end
	return true;
end;
Hub.ScanMaps = function(self)
	local lobby = self:GetLobby();
	local pads = {LUAOBFUSACTOR_DECRYPT_STR_0("\129\0\164\17\124\28\179\94", "\125\215\111\208\116\44"),"VotePad2",LUAOBFUSACTOR_DECRYPT_STR_0("\49\72\91\246\72\93\3\20", "\60\103\39\47\147\24")};
	local result = {};
	for _, padName in ipairs(pads) do
		local pad = self:GetVotePad(padName);
		local mapName = "";
		local votes = "";
		local imageId = "";
		if pad then
			local vig = pad:FindFirstChild("VoteInfoGui") or pad:FindFirstChildWhichIsA("BillboardGui", true) or pad:FindFirstChildWhichIsA("SurfaceGui", true);
			if vig then
				local mn = vig:FindFirstChild("MapName", true);
				if (mn and mn:IsA("TextLabel") and (mn.Text ~= "")) then
					mapName = mn.Text;
				end
				local vt = vig:FindFirstChild("Votes", true);
				if (vt and vt:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\216\15\239\148\250\242\76\233\6", "\46\140\106\151\224\182\147")) and (vt.Text ~= "")) then
					votes = vt.Text;
				end
			end
			local mig = pad:FindFirstChild("MapInfoGui");
			if mig then
				local mi = mig:FindFirstChild("MapIcon", true);
				if (mi and mi:IsA("ImageLabel") and (mi.Image ~= "")) then
					imageId = mi.Image;
				end
			end
			local voteIcons = (lobby and lobby:FindFirstChild("VoteIcons")) or (lobby and lobby:FindFirstChild("VotePads") and lobby.VotePads:FindFirstChild("VoteIcons"));
			if voteIcons then
				local viPad = voteIcons:FindFirstChild(padName);
				if viPad then
					local img = viPad:FindFirstChildWhichIsA("ImageLabel", true);
					if (img and (img.Image ~= "")) then
						imageId = img.Image;
					end
				end
			end
		end
		if not self.Maps.Cached[padName] then
			self.Maps.Cached[padName] = {MapName=padName,Votes="0",Image=Icons.MapFallback};
		end
		if ((mapName ~= "") and (mapName ~= "Unknown Map")) then
			self.Maps.Cached[padName].MapName = mapName;
		end
		if (votes ~= "") then
			self.Maps.Cached[padName].Votes = votes;
		end
		if (imageId ~= "") then
			self.Maps.Cached[padName].Image = imageId;
		end
		table.insert(result, {PadName=padName,[LUAOBFUSACTOR_DECRYPT_STR_0("\219\44\121", "\34\139\77\29")]=pad,MapName=self.Maps.Cached[padName].MapName,Votes=self.Maps.Cached[padName].Votes,Image=self.Maps.Cached[padName].Image});
	end
	return result;
end;
Hub.TeleportToPad = function(self, padName)
	if not self:IsVotingActive() then
		return;
	end
	local pad = self:GetVotePad(padName);
	if not pad then
		return;
	end
	local targetPart = nil;
	if pad:IsA("BasePart") then
		targetPart = pad;
	else
		for _, p in ipairs(pad:GetChildren()) do
			if (p:IsA("BasePart") and p:FindFirstChildOfClass(LUAOBFUSACTOR_DECRYPT_STR_0("\132\255\8\87\33\132\226\28\90\58\189\249\9\64\44\162", "\73\208\144\125\52"))) then
