	self:Corner(btn, 5);
	self:Stroke(btn, Color3.fromRGB(38, 43, 58), 1);
	local curr = default;
	btn.MouseEnter:Connect(function()
		self:Tween(btn, {BackgroundColor3=Color3.fromRGB(34, 40, 56)}, 0.15);
	end);
	btn.MouseLeave:Connect(function()
		self:Tween(btn, {[LUAOBFUSACTOR_DECRYPT_STR_0("\89\65\118\58\197\171\189\144\117\68\86\62\206\182\160\214", "\229\27\32\21\81\162\217\210")]=Color3.fromRGB(26, 26, 34)}, 0.15);
	end);
	btn.MouseButton1Click:Connect(function()
		local opts = ((type(options) == "function") and options()) or options;
		if (not opts or (#opts == 0)) then
			btn.Text = "None";
			return;
		end
		local found = false;
		for idx, val in ipairs(opts) do
			if (val == curr) then
				curr = opts[(idx % #opts) + 1];
				found = true;
				break;
			end
		end
		if not found then
			curr = opts[1];
		end
		btn.Text = tostring(curr);
