			frameCount = frameCount + 1;
			local now = os.clock();
			if ((now - lastTime) >= 0.5) then
				currentFps = math.floor(frameCount / (now - lastTime));
				frameCount = 0;
				lastTime = now;
				if (self.State.WatermarkLabel and self.Config.Toggles.Watermark) then
					local pingMs = 45;
					pcall(function()
						local stats = game:GetService(LUAOBFUSACTOR_DECRYPT_STR_0("\150\36\129\102\86", "\37\197\80\224\18"));
